select job_id, printer_id, terminal_id, stage, claim_cnt, claimed_at, lease_until, closed_at
  from wms_print_dispatch where job_id = #{jobId}
   for update

select printer_id, state_cd, errors, warnings, odometer, odometer_base, src, detail, checked_at, changed_at
  from wms_printer_status where printer_id = #{printerId}
   for update
